const out = uniqueStrings(input);
console.log('out:', JSON.stringify(out));
console.assert(JSON.stringify(out) === JSON.stringify(['Apple', 'banana', 'cherry']), 'FAIL basic');

// Input not mutated
console.assert(JSON.stringify(input) === JSON.stringify(['Apple', 'banana', 'APPLE', 'Banana', 'cherry', 'apple']), 'FAIL mutation');

// Whitespace not trimmed
const ws = uniqueStrings([' a ', 'a', ' a ']);
console.log('ws:', JSON.stringify(ws));
console.assert(JSON.stringify(ws) === JSON.stringify([' a ', 'a']), 'FAIL whitespace');

// Empty array
console.assert(JSON.stringify(uniqueStrings([])) === JSON.stringify([]), 'FAIL empty');

// Single element
console.assert(JSON.stringify(uniqueStrings(['x'])) === JSON.stringify(['x']), 'FAIL single');

// All duplicates
console.assert(JSON.stringify(uniqueStrings(['a', 'A', 'a'])) === JSON.stringify(['a']), 'FAIL all dup');

// Returns a new array (not same reference)
const arr = ['a'];
const res = uniqueStrings(arr);
console.assert(res !== arr, 'FAIL new array reference');

console.log('All checks passed.');
"

